            cJSON_AddNumberToObject(j, "sFieldGoalsMade", x->s_field_goals_made);
            cJSON_AddNumberToObject(j, "sFieldGoalsPercentage", x->s_field_goals_percentage);
            cJSON_AddNumberToObject(j, "sFoulsOn", x->s_fouls_on);
