char * cJSON_PrintPl(const struct Pl * x) {
    char * s = NULL;
    if (NULL != x) {
        cJSON * j = cJSON_CreatePl(x);
        if (NULL != j) {
            s = cJSON_Print(j);
            cJSON_Delete(j);
        }
    }
    return s;
}

void cJSON_DeletePl(struct Pl * x) {
    if (NULL != x) {
        if (NULL != x->captain) {
            cJSON_free(x->captain);
        }
        if (NULL != x->comp) {
            cJSON_DeleteComp(x->comp);
        }
        if (NULL != x->family_name) {
            cJSON_free(x->family_name);
        }
        if (NULL != x->first_name) {
            cJSON_free(x->first_name);
        }
        if (NULL != x->international_family_name) {
            cJSON_free(x->international_family_name);
        }
        if (NULL != x->international_first_name) {
            cJSON_free(x->international_first_name);
        }
        if (NULL != x->name) {
            cJSON_free(x->name);
        }
        if (NULL != x->playing_position) {
            cJSON_free(x->playing_position);
        }
        if (NULL != x->s_minutes) {
            cJSON_DeleteSMinutes(x->s_minutes);
        }
        if (NULL != x->shirt_number) {
            cJSON_free(x->shirt_number);
        }
        cJSON_free(x);
    }
}

